// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Initializer init;

    function setUp() public {
        c = new C();
        init = new Initializer();
    }

    function testFuzz_property(uint256 seed) public {
        // deploy a stub oracle embodying the fuzzed seed (adversarial environment construction:
        // the registered oracle must be a contract, which a raw fuzzed address cannot be)
        OracleStub oracle = new OracleStub(seed);

        // register it through initialize(); msg.sender must hold code, so route via helper
        init.init(c, address(oracle), bytes30(uint240(seed)));

        // GENERAL RULE: for any admissible registration inputs, oracle() returns exactly
        // the oracle address that was registered at initialization.
        assertTrue(c.oracle() == IOracleProvider(address(oracle)), "oracle() must return registered oracle");
    }
}

contract Initializer {
    function init(C c, address oracle, bytes30 data) external {
        IProduct.ProductInfo memory info;
        info.name = "t";
        info.symbol = "T";
        info.payoffDefinition = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType(1),
            payoffDirection: PayoffDefinitionLib.PayoffDirection(1),
            data: data
        });
        info.oracle = IOracleProvider(oracle);
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });
        c.initialize(info);
    }
}

contract OracleStub is IOracleProvider {
    uint256 public seed;
    constructor(uint256 s) { seed = s; }
    function sync() external pure returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function currentVersion() external pure returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function atVersion(uint256) external pure returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
