pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IProductInit {
    function initialize(
        tuple(
            string,
            string,
            tuple(uint8, uint8, bytes30),
            address,
            uint256,
            uint256,
            uint256,
            uint256,
            uint256,
            uint256,
            tuple(int128, int128, int128, uint128)
        ) calldata productInfo
    ) external;
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(
        uint8 payoffType,
        uint8 payoffDirection,
        bytes30 payoffData,
        uint256 maintenance,
        uint256 fundingFee,
        uint256 makerFee,
        uint256 takerFee,
        uint256 positionFee,
        uint256 makerLimit,
        int128 minRate,
        int128 maxRate,
        int128 targetRate,
        uint128 targetUtilization
    ) public {
        // keep fees in the admissible domain (<= 1e18, i.e. <= ONE)
        maintenance = bound(maintenance, 0, 1e18);
        fundingFee = bound(fundingFee, 0, 1e18);
        makerFee = bound(makerFee, 0, 1e18);
        takerFee = bound(takerFee, 0, 1e18);
        positionFee = bound(positionFee, 0, 1e18);
        makerLimit = bound(makerLimit, 0, 1e18);

        // the oracle must be a contract with code; the test contract itself is a
        // valid code-bearing address that satisfies this environment requirement
        address oracleAddr = address(this);

        bytes memory initCalldata = abi.encodeWithSignature(
            "initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))",
            (
                string("T"),
                string("T"),
                (payoffType, payoffDirection, payoffData),
                oracleAddr,
                maintenance,
                fundingFee,
                makerFee,
                takerFee,
                positionFee,
                makerLimit,
                (minRate, maxRate, targetRate, targetUtilization)
            )
        );

        bool initialized;
        (bool ok, ) = address(c).call(initCalldata);
        initialized = ok;
        // only reason about runs where the whole initialization succeeded
        vm.assume(initialized);

        // Rule: for any admissible initialization, oracle() must return the
        // registered oracle address (nonzero); the mutant always returns
        // address(0), breaking this for every such input.
        assertTrue(address(c.oracle()) != address(0), "oracle() must return the registered oracle, not zero");
    }
}

