pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 versionSeed, uint256 priceSeed) public {
        uint256 version = bound(versionSeed, 1, type(uint64).max);
        int256 price = int256(bound(priceSeed, 0, type(uint128).max));

        StubOracle oracle = new StubOracle(version, price);

        IProduct.ProductInfo memory info;
        info.name = "T";
        info.symbol = "T";
        info.payoffDefinition = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.PassThrough,
            payoffDirection: PayoffDefinitionLib.PayoffDirection.Long,
            data: bytes30(0)
        });
        info.oracle = oracle;
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(type(uint256).max);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        bool initialized;
        try c.initialize(info) { initialized = true; } catch { initialized = false; }
        vm.assume(initialized);

        // Rule: for any admissible initialization, the product exposes a working oracle:
        // reading the current oracle version through the registered oracle must complete.
        bool ok;
        try c.currentVersion() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract StubOracle {
    uint256 public v;
    int256 public p;

    constructor(uint256 version_, int256 price_) {
        v = version_;
        p = price_;
    }

    function _ov() internal view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: v, timestamp: block.timestamp, price: Fixed18.wrap(p)});
    }

    function sync() external returns (IOracleProvider.OracleVersion memory) { return _ov(); }
    function currentVersion() external view returns (IOracleProvider.OracleVersion memory) { return _ov(); }
    function atVersion(uint256) external view returns (IOracleProvider.OracleVersion memory) { return _ov(); }
}

