pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Initializer initializer;

    function setUp() public {
        c = new C();
        initializer = new Initializer();
    }

    function testFuzz_property(uint256 seed) public {
        // Admissible domain: any seed (used to parameterize the registered oracle's behavior/version data).
        OracleStub oracleStub = new OracleStub(seed);

        // Initialize the product from a contract context (initialize() requires msg.sender to be a contract).
        initializer.init(address(c), address(oracleStub), seed);

        // General rule: after successful initialization, the product's oracle() getter must expose
        // the registered (non-zero, code-bearing) oracle address that was passed in.
        assertTrue(
            address(c.oracle()) != address(0) && address(c.oracle()).code.length > 0,
            "oracle() must return the registered non-zero oracle"
        );
    }
}

// Minimal registered oracle: contract-bearing address implementing the pieces needed at init.
contract OracleStub {
    uint256 private _seed;
    constructor(uint256 seed) { _seed = seed; }
    function sync() external view returns (uint256, uint256, int256) {
        return (_seed == 0 ? 1 : _seed, block.timestamp, 0);
    }
    function currentVersion() external view returns (uint256, uint256, int256) {
        return (_seed == 0 ? 1 : _seed, block.timestamp, 0);
    }
    function atVersion(uint256) external pure returns (uint256, uint256, int256) {
        return (1, block.timestamp, 0);
    }
}

// Helper performing initialize() from a contract context, with hand-built calldata for
// initialize(ProductInfo) so the test file does not need the interface types.
contract Initializer {
    struct PD { uint8 payoffType; uint8 payoffDirection; bytes30 data; }
    struct Curve { int128 minRate; int128 maxRate; int128 targetRate; uint128 targetUtilization; }
    struct Info {
        string name;
        string symbol;
        PD payoffDefinition;
        address oracle;
        uint256 maintenance;
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit;
        Curve utilizationCurve;
    }

    function init(address product, address oracle, uint256 seed) external {
        Info memory info = Info({
            name: "P",
            symbol: "P",
            payoffDefinition: PD({payoffType: 0, payoffDirection: 0, data: bytes30(0)}),
            oracle: oracle,
            maintenance: 1e18,
            fundingFee: 0,
            makerFee: 0,
            takerFee: 0,
            positionFee: 0,
            makerLimit: type(uint256).max / 2,
            utilizationCurve: Curve({minRate: 0, maxRate: 0, targetRate: 0, targetUtilization: 0})
        });
        (bool ok, ) = product.call(
            abi.encodeWithSelector(
                bytes4(keccak256("initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))")),
                info
            )
        );
        require(ok, "init failed");
    }
}

