pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seedPrice, uint256 seedData) public {
        uint256 price = bound(seedPrice, 0, 1e24);
        uint256 data = bound(seedData, 0, 1e30);

        MockOracle oracle = new MockOracle(price);

        // Build ProductInfo calldata via low-level call so the externally
        // registered oracle address is the deciding fuzz-driven value.
        string memory name = "P";
        string memory symbol = "PS";
        bytes memory payload = abi.encodeWithSignature(
            "initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))",
            name,
            symbol,
            uint8(0),                 // payoffType
            uint8(0),                 // payoffDirection
            bytes30(uint248(data)),   // data
            address(oracle),          // oracle: the registered counterparty
            uint256(1e18),            // maintenance
            uint256(0),               // fundingFee
            uint256(0),               // makerFee
            uint256(0),               // takerFee
            uint256(0),               // positionFee
            uint256(1e24),            // makerLimit
            int128(1e17),             // minRate
            int128(5e17),             // maxRate
            int128(2e17),             // targetRate
            uint128(8e17)             // targetUtilization
        );

        (bool ok, ) = address(c).call(payload);
        if (!ok) {
            // initialization not admissible for these fuzzed params; nothing to check
            return;
        }

        // General rule: a successfully initialized product must expose, through
        // its public surface, the exact oracle contract it was registered with.
        assertTrue(address(c.oracle()) == address(oracle));
    }
}

contract MockOracle {
    uint256 public price;

    constructor(uint256 price_) { price = price_; }

    function sync() external returns (uint256, uint256, int256) {
        return (1, block.timestamp, int256(price));
    }

    function currentVersion() external view returns (uint256, uint256, int256) {
        return (1, block.timestamp, int256(price));
    }

    function atVersion(uint256) external view returns (uint256, uint256, int256) {
        return (1, block.timestamp, int256(price));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint8 payoffType, uint8 payoffDirection, bytes30 data) public {
        // admissible domain: non-default enum variants (0 is invalid/zeroed default)
        payoffType = uint8(bound(payoffType, 1, 3));
        payoffDirection = uint8(bound(payoffDirection, 1, 2));

        // oracle must be a contract for initialization to succeed
        OracleStub oracle = new OracleStub();

        // manually ABI-encode ProductInfo calldata (struct types are not importable here):
        // (string name, string symbol, (uint8,uint8,bytes30) payoffDefinition, address oracle,
        //  6 x uint256 params, (int128,int128,int128,uint128) utilizationCurve)
        bytes memory productInfo = abi.encodePacked(
            uint256(0x160),          // offset of name
            uint256(0x1A0),          // offset of symbol (name takes 2 slots)
            uint256(payoffType),     // payoffDefinition.payoffType (static tuple)
            uint256(payoffDirection),// payoffDefinition.payoffDirection
            bytes32(data),           // payoffDefinition.data
            bytes32(uint256(uint160(address(oracle)))),
            uint256(1e18),           // maintenance
            uint256(0),              // fundingFee
            uint256(0),              // makerFee
            uint256(0),              // takerFee
            uint256(0),              // positionFee
            uint256(1e24),           // makerLimit
            bytes32(uint256(uint128(0))), // curve.minRate
            bytes32(uint256(uint128(1e18))), // curve.maxRate
            bytes32(uint256(uint128(5e17))), // curve.targetRate
            bytes32(uint256(uint128(8e17)))  // curve.targetUtilization
        );

        vm.prank(address(this));
        (bool ok, ) = address(c).call(abi.encodePacked(c.initialize.selector, productInfo));
        require(ok, "initialize failed");

        // RULE: payoffDefinition() must return the definition that was stored,
        // for every admissible input.
        assertTrue(
            uint8(c.payoffDefinition().payoffType) == payoffType &&
            uint8(c.payoffDefinition().payoffDirection) == payoffDirection &&
            c.payoffDefinition().data == data,
            "payoffDefinition must return the stored definition"
        );
    }
}

contract OracleStub {
    // minimal contract with code so Address.isContract(oracle) passes at initialization
}
